practiceChallenge.solutionCode:
def batch(iterable, size):
    chunk = []
    for item in iterable:
        chunk.append(item)
        if len(chunk) == size:
            yield chunk
            chunk = []
    if chunk:
        yield chunk

for b in batch(range(7), 3):
    print(b)

