def audit_log(func):
    def wrapper(*args, **kwargs):
        print(f"[AUDIT] Calling {func.__name__} with {args}")
        result = func(*args, **kwargs)
        print(f"[AUDIT] {func.__name__} returned {result}")
        return result
    return wrapper

@audit_log
def add(a, b):
    return a + b

