practiceChallenge.solutionCode:
#include <iostream>

void reverseArray(int* start, int* end) {
    while (start < end) {
        int temp = *start;
        *start = *end;
        *end = temp;
        start++;
        end--;
    }
}

int main() {
    int arr[] = {1, 2, 3, 4, 5, 6};
    size_t n = sizeof(arr) / sizeof(arr[0]);

    std::cout << "Original: ";
    for (size_t i = 0; i < n; i++) std::cout << arr[i] << " ";
    std::cout << "\n";

    reverseArray(arr, arr + n - 1);

    std::cout << "Reversed: ";
    for (size_t i = 0; i < n; i++) std::cout << arr[i] << " ";
    std::cout << "\n";
    return 0;
}

