uintptr_t alignForward(uintptr_t ptr, size_t alignment) {
    uintptr_t p = ptr;
    uintptr_t a = static_cast<uintptr_t>(alignment);
    uintptr_t modulo = p & (a - 1);
    if (modulo != 0) {
        p += (a - modulo);
    }
    return p;
}

