practiceChallenge.solutionCode:
#include <iostream>
#include <utility>

template <typename T>
class UniquePtr {
private:
    T* m_ptr{nullptr};

public:
    explicit UniquePtr(T* ptr = nullptr) : m_ptr(ptr) {}

    ~UniquePtr() {
        delete m_ptr;
        m_ptr = nullptr;
    }

    // Delete copy operations
    UniquePtr(const UniquePtr&) = delete;
    UniquePtr& operator=(const UniquePtr&) = delete;

    // Move Constructor
    UniquePtr(UniquePtr&& other) noexcept : m_ptr(other.m_ptr) {
        other.m_ptr = nullptr;
    }

    // Move Assignment
    UniquePtr& operator=(UniquePtr&& other) noexcept {
        if (this != &other) {
            delete m_ptr;
            m_ptr = other.m_ptr;
            other.m_ptr = nullptr;
        }
        return *this;
    }

    T& operator*() const { return *m_ptr; }
    T* operator->() const { return m_ptr; }
    T* get() const { return m_ptr; }
};

struct Point {
    int x, y;
};

int main() {
    UniquePtr<Point> p1(new Point{10, 20});
    std::cout << "Point coordinates: (" << p1->x << ", " << p1->y << ")\n";

    UniquePtr<Point> p2 = std::move(p1);
    std::cout << "Moved point coordinates: (" << p2->x << ", " << p2->y << ")\n";
    std::cout << "p1 is now null: " << (p1.get() == nullptr ? "YES" : "NO") << "\n";
    return 0;
}

