template <typename T>
std::string formatItem(T value) {
    if constexpr (std::is_pointer_v<T>) {
        if (!value) return "nullptr";
        return std::to_string(*value);
    } else if constexpr (std::is_same_v<T, bool>) {
        return value ? "true" : "false";
    } else {
        return std::to_string(value);
    }
}

