def master_theorem(a: int, b: int, d: float):
    log_b_a = math.log(a, b)
    if abs(d - log_b_a) < 1e-9:
        return f"Case 2 (Balanced): O(N^{d:.0f} * log N)"
    elif d < log_b_a:
        return f"Case 1 (Leaf dominated): O(N^{log_b_a:.2f})"
    else:
