def reverse_words(s: str) -> str:
    words = []
    i = len(s) - 1

    while i >= 0:
        # Skip trailing/interstitial spaces
        while i >= 0 and s[i] == ' ':
            i -= 1
        if i < 0: break

        # Find word boundary
        j = i
        while i >= 0 and s[i] != ' ':
            i -= 1
        words.append(s[i + 1:j + 1])

    return " ".join(words)

