def find_min(nums: list[int]) -> int:
    left, right = 0, len(nums) - 1

    while left < right:
        mid = left + (right - left) // 2
        if nums[mid] > nums[right]:
            left = mid + 1 # inflection point is to the right
        else:
            right = mid    # mid could be minimum or to the left

    return nums[left]

