def first_missing_positive(nums: list[int]) -> int:
    n = len(nums)

    for i in range(n):
        # Swap nums[i] into its correct index nums[i] - 1
        while 1 <= nums[i] <= n and nums[nums[i] - 1] != nums[i]:
            target_idx = nums[i] - 1
            nums[i], nums[target_idx] = nums[target_idx], nums[i]

    # Find the first mismatch
    for i in range(n):
        if nums[i] != i + 1:
            return i + 1

    return n + 1

