class MonotonicQueue:
    def __init__(self):
        self.q = deque()

    def push(self, val: int):
        # Eliminate all smaller elements from the back
        while self.q and self.q[-1] < val:
            self.q.pop()
        self.q.append(val)

    def pop(self, val: int):
        if self.q and self.q[0] == val:
            self.q.popleft()

    def max(self) -> int:
        return self.q[0]

