def constrained_subset_sum(nums: list[int], k: int) -> int:
    q = deque() # stores indices
    dp = nums.copy()

    for i in range(len(nums)):
        # Remove expired window elements
        if q and q[0] < i - k:
            q.popleft()

        if q:
            dp[i] = max(dp[i], nums[i] + dp[q[0]])

        while q and dp[q[-1]] <= dp[i]:
            q.pop()

        if dp[i] > 0:
            q.append(i)

    return max(dp)

