class ThreadSafeStack:
    def __init__(self):
        self._data = []
        self._lock = threading.Lock()

    def push(self, val):
        with self._lock:
            self._data.append(val)

    def pop(self):
        with self._lock:
            if not self._data: return None
            return self._data.pop()

