def morris_inorder(root: TreeNode) -> list[int]:
    res = []
    curr = root

    while curr:
        if not curr.left:
            res.append(curr.val)
            curr = curr.right
        else:
            # Find inorder predecessor
            pred = curr.left
            while pred.right and pred.right != curr:
                pred = pred.right

            if not pred.right:
                pred.right = curr # establish thread
                curr = curr.left
            else:
                pred.right = None # restore original tree structure
                res.append(curr.val)
                curr = curr.right

    return res

