def insert_into_bst(root: TreeNode, val: int) -> TreeNode:
    if not root: return TreeNode(val)
    curr = root

    while True:
        if val < curr.val:
            if not curr.left:
                curr.left = TreeNode(val)
                break
            curr = curr.left
        else:
            if not curr.right:
                curr.right = TreeNode(val)
                break
            curr = curr.right

    return root

