def find_words_2d(board: list[list[str]], words: list[str]) -> list[str]:
    # 1. Build Trie
    root = {}
    for word in words:
        curr = root
        for c in word:
            curr = curr.setdefault(c, {})
        curr['$'] = word # '$' marks end of word and stores payload

    rows, cols = len(board), len(board[0])
    res = []

    def dfs(r, c, parent_node):
        char = board[r][c]
        curr_node = parent_node.get(char)
        if not curr_node: return

        # Word found!
        if '$' in curr_node:
            res.append(curr_node['$'])
            del curr_node['$'] # prevent duplicate matches

        board[r][c] = '#' # mark visited in-place
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and board[nr][nc] != '#':
                dfs(nr, nc, curr_node)
        board[r][c] = char # unmark visited (backtrack)

    for r in range(rows):
        for c in range(cols):
            dfs(r, c, root)

    return res

