def alien_order(words: list[str]) -> str:
    adj = {c: set() for w in words for c in w}
    in_degree = {c: 0 for c in adj}

    for i in range(len(words) - 1):
        w1, w2 = words[i], words[i + 1]
        min_len = min(len(w1), len(w2))
        if len(w1) > len(w2) and w1[:min_len] == w2[:min_len]:
            return "" # Invalid prefix order!

        for j in range(min_len):
            if w1[j] != w2[j]:
                if w2[j] not in adj[w1[j]]:
                    adj[w1[j]].add(w2[j])
                    in_degree[w2[j]] += 1
                break # only first mismatch matters

    q = deque([c for c in in_degree if in_degree[c] == 0])
    res = []
    while q:
        c = q.popleft()
        res.append(c)
        for neighbor in adj[c]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                q.append(neighbor)

    return "".join(res) if len(res) == len(in_degree) else ""

print("Alien alphabet:", alien_order(["wrt","wrf","er","ett","rftt"])) # "wertf"

import heapq

def dijkstra(n: int, edges: list[list[int]], src: int) -> dict[int, int]:
    # edges: [u, v, weight]
    adj = defaultdict(list)
    for u, v, w in edges:
        adj[u].append((v, w))

    dist = {i: float('inf') for i in range(n)}
    dist[src] = 0
    pq = [(0, src)] # (distance, node)

    while pq:
        d, u = heapq.heappop(pq)

        # Skip stale entries
        if d > dist[u]:
            continue

        for v, weight in adj[u]:
            new_dist = d + weight
            if new_dist < dist[v]:
                dist[v] = new_dist
                heapq.heappush(pq, (new_dist, v))

    return dist

w_edges = [[0, 1, 4], [0, 2, 1], [2, 1, 2], [1, 3, 1], [2, 3, 5]]
print("Shortest distances from 0:", dijkstra(4, w_edges, 0)) # {0: 0, 1: 3, 2: 1, 3: 4}

def network_delay_time(times: list[list[int]], n: int, k: int) -> int:
    adj = defaultdict(list)
    for u, v, w in times:
        adj[u].append((v, w))

    dist = {}
    pq = [(0, k)]

    while pq:
        d, u = heapq.heappop(pq)
        if u in dist: continue
        dist[u] = d

        for v, w in adj[u]:
            if v not in dist:
                heapq.heappush(pq, (d + w, v))

    if len(dist) == n:
        return max(dist.values())
    return -1

times = [[2,1,1],[2,3,1],[3,4,1]]
print("Network Delay Time from node 2:", network_delay_time(times, 4, 2)) # 2

def bellman_ford(n: int, edges: list[list[int]], src: int):
    dist = [float('inf')] * n
    dist[src] = 0

    # 1. Relax edges V - 1 times
    for _ in range(n - 1):
        for u, v, w in edges:
            if dist[u] != float('inf') and dist[u] + w < dist[v]:
                dist[v] = dist[u] + w

    # 2. Check for negative weight cycles
    for u, v, w in edges:
        if dist[u] != float('inf') and dist[u] + w < dist[v]:
            raise ValueError("Graph contains a negative weight cycle!")

    return dist

