def longest_common_subsequence(text1: str, text2: str) -> int:
    m, n = len(text1), len(text2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if text1[i - 1] == text2[j - 1]:
                dp[i][j] = 1 + dp[i - 1][j - 1]
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    return dp[m][n]

print("LCS of 'abcde' and 'ace':", longest_common_subsequence("abcde", "ace")) # 3 ("ace")

def min_distance(word1: str, word2: str) -> int:
    m, n = len(word1), len(word2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1): dp[i][0] = i # delete all
    for j in range(n + 1): dp[0][j] = j # insert all

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if word1[i - 1] == word2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(
                    dp[i - 1][j],     # Delete
                    dp[i][j - 1],     # Insert
                    dp[i - 1][j - 1]  # Replace
                )

    return dp[m][n]

print("Edit distance 'horse' to 'ros':", min_distance("horse", "ros")) # 3

def unique_paths_with_obstacles(obstacleGrid: list[list[int]]) -> int:
    if not obstacleGrid or obstacleGrid[0][0] == 1:
        return 0

    cols = len(obstacleGrid[0])
    dp = [0] * cols
    dp[0] = 1 # Start cell

    for row in obstacleGrid:
        for c in range(cols):
            if row[c] == 1:
                dp[c] = 0 # Obstacle blocks path
            elif c > 0:
                dp[c] += dp[c - 1] # Paths from left

    return dp[cols - 1]

